             verticalArrangement = if (expanded) Arrangement.Bottom else Arrangement.Center,
             horizontalAlignment = Alignment.End,
         ) {
             if (expanded) {
                 OcrControlMenuCard(
                     rows = menuRows(),
                     // Ширину окна держим фиксированной, а по высоте следим за
