    /**
     * Ручной ввод: в сторонней игре скопировать текст нечем, а положить его
     * в буфер можно и отсюда.
     */
    @Composable
    private fun panelInput() {
        OutlinedTextField(
            value = inputText.value,
            onValueChange = { inputText.value = it },
            label = { Text("Текст для бабла") },
            singleLine = true,
            modifier = Modifier
                .fillMaxWidth()
                .onFocusChanged { state -> uiHandler.post { setWindowFocusable(state.isFocused) } },
        )
        Spacer(Modifier.height(PANEL_GAP_DP.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(PANEL_GAP_DP.dp)) {
            OcrMenuActionButton(
                OcrMenuAction(
                    icon = Icons.Outlined.PlayArrow,
                    contentDescription = "Озвучить введённый текст",
                    onClick = {
                        val typed = inputText.value.trim()
                        if (typed.isNotBlank()) speakText(typed)
                    },
                ),
            )
            OcrMenuActionButton(
                OcrMenuAction(
                    icon = Icons.Outlined.Close,
                    contentDescription = "Очистить введённый текст",
                    onClick = {
                        inputText.value = ""
                        bubble.value = ""
                    },
                ),
            )
        }
    }

    /**
     * Чтение рамки: без Службы доступности листать нечем, поэтому сразу
     * отводим читателя в настройки, а не ограничиваемся тостом.
     */
    /** Разовый скан области: один кадр → распознать → показать и озвучить. */
    private fun scanOnce() {
        if (isReading) stopReading()
        pendingScanOnce = true
        OcrCaptureActivity.request(applicationContext)
    }

    private fun scanOnceWith(projection: android.media.projection.MediaProjection) {
        projectionGranted = true
        runCatching { ensureForeground() }
        val dm = resources.displayMetrics
        val rect = fixedRegionRect() ?: Rect(0, 0, dm.widthPixels, dm.heightPixels)
        val engine = OverlayCaptureEngine(applicationContext, projection)
        val reader = OverlayAutoReader(applicationContext, engine)
        serviceScope.launch {
            try {
                uiHandler.post { toast("Скан: ${reader.engineTitle()}") }
                val text = runCatching { reader.readOnce(rect) }.getOrNull()
                uiHandler.post {
                    if (text.isNullOrBlank()) {
                        toast("Текст не распознан")
                    } else {
                        setBubble(text)
                        expandNow()
                        speakText(text)
                    }
                }
            } finally {
                runCatching { engine.stop() }
                runCatching { projection.stop() }
            }
        }
    }

    /** Скорость озвучки (−/+) — как слайдер скорости в читалке. */
    private fun changeSpeechRate(delta: Float) {
        val next = (prefs.speechRate().get() + delta).coerceIn(0.5f, 2.0f)
        prefs.speechRate().set(next)
        speechRateUi.value = next
    }

    /** Движок OCR оверлея по кругу (ONNX/онлайн/…): не уходим в настройки. */
    private fun cycleOverlayEngine() {
        val models = mihon.domain.ocr.model.OcrModel.values().toList()
        if (models.isEmpty()) return
        val idx = models.indexOf(prefs.appOcrEngine().get()).coerceAtLeast(0)
        val next = models[(idx + 1) % models.size]
        prefs.appOcrEngine().set(next)
        prefs.overlayOwnEngine().set(true)
        toast("Движок оверлея: ${mihon.data.ocr.OcrPlugins.byModel(next).title}")
    }

    private fun toggleFrameReading() {
        if (isReading) {
            stopReading()
            return
        }
        if (!OverlayGestureService.isEnabled()) {
            toast("Без Службы доступности листать нечем — включаю настройки")
            requestGestureService()
            return
        }
        OcrCaptureActivity.request(applicationContext)
    }


    /** Женский ли голос выбран в настройках — от этого зависит вид кнопок. */
    private fun voiceIsFemale(): Boolean {
        val gender = runCatching { prefs.voicePresetGender().get() }.getOrNull()
        return gender != "male"
    }

    private fun openOverlaySettings() {
        // Экран настроек живёт внутри приложения, а сервис оверлея —
        // снаружи. Открываем приложение: оверлей сам спрячется, как только
        // заметит, что мы на переднем плане.
        runCatching {
            val launch = packageManager.getLaunchIntentForPackage(packageName)
            launch?.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK)
            launch?.let { startActivity(it) }
        }.onFailure { toast("Открой настройки оверлея в приложении") }
    }

    private fun dragPanelBy(delta: Offset) {
        val lp = params ?: return
        lp.x += delta.x.roundToInt()
        lp.y += delta.y.roundToInt()
        clampToScreen(lp)
        runCatching { root?.let { wm.updateViewLayout(it, lp) } }
    }

    /**
     * Отпустили кнопку: прижимаем панель к краю и запоминаем место.
     *
     * Раньше кнопка оставалась там, где палец оторвался, и её легко было
     * не заметить или задеть.
     */
    private fun settlePanel() {
        val lp = params ?: return
        clampToScreen(lp)
        snapToCorner(lp)
        savePanelPosition(lp)
        runCatching { root?.let { wm.updateViewLayout(it, lp) } }
    }

    private fun savePanelPosition(lp: WindowManager.LayoutParams) {
        getSharedPreferences(POSITION_PREFS, Context.MODE_PRIVATE)
            .edit()
            .putInt(KEY_POS_X, lp.x)
            .putInt(KEY_POS_Y, lp.y)
            .apply()
    }


    /**
     * Прижать к краю экрана — как кнопка в углу у читалки.
     *
     * Раньше панель оставалась там, куда её перетащили, и у краёв экрана
     * наполовину уезжала за него. Теперь она всегда стоит у края: по
     * горизонтали — к ближайшему боку, по вертикали — к нижней трети, где
     * до кнопки не достаёт большой палец.
     */
    private fun snapToCorner(lp: WindowManager.LayoutParams) {
        val dm = resources.displayMetrics
        val margin = dp(CORNER_MARGIN_DP)
        val toLeft = lp.x + lp.width / 2 < dm.widthPixels / 2
        lp.x = if (toLeft) margin else (dm.widthPixels - lp.width - margin)
        val bottomZone = dm.heightPixels * 2 / 3
        lp.y = if (lp.y < bottomZone) {
            margin
        } else {
            (dm.heightPixels - lp.height - margin).coerceAtLeast(margin)
        }
    }

    private fun makeFocusable(value: Boolean) {
        val lp = params ?: return
        lp.flags = if (value) {
            lp.flags and WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE.inv()
        } else {
            lp.flags or WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE
        }
        runCatching { root?.let { wm.updateViewLayout(it, lp) } }
    }

    /**
     * Окну нужно фокусируемое состояние только пока в фокусе поле ввода:
     * иначе поле не раскроет клавиатуру. Пересоздавать флаги на каждый
     * щелчок нельзя — система зря дёргает окно.
     */
    private fun setWindowFocusable(value: Boolean) {
        if (windowFocusable == value) return
        windowFocusable = value
        makeFocusable(value)
    }

    private var windowFocusable = false


    private fun clampToScreen(lp: WindowManager.LayoutParams) {
        val dm = resources.displayMetrics
        lp.x = lp.x.coerceIn(0, (dm.widthPixels - lp.width).coerceAtLeast(0))
        lp.y = lp.y.coerceIn(0, (dm.heightPixels - lp.height).coerceAtLeast(0))
    }

    private fun toast(msg: String) {
        uiHandler.post { Toast.makeText(this, msg, Toast.LENGTH_SHORT).show() }
    }

    override fun onDestroy() {
        stopReading()
        // Цикл чтения живёт в serviceScope: без отмены задача продолжала бы
        // держать сервис и захват после его смерти.
        serviceScope.cancel()
        (applicationContext as? Application)?.unregisterActivityLifecycleCallbacks(ownActivityWatcher)
        // Композиция панели держит ViewTreeLifecycleOwner: без перевода
        // жизненного цикла в DESTROYED она не освободится.
        runCatching { panelLifecycleOwner.registry.currentState = Lifecycle.State.DESTROYED }
        panelViewModelOwner.viewModelStore.clear()
        runCatching { stt?.destroy() }
        stt = null
        runCatching { readEngine.stop() }
        val cm = getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager
        clipListener?.let { runCatching { cm.removePrimaryClipChangedListener(it) } }
        closeSelector()
        frameRoot?.let { runCatching { wm.removeView(it) } }
        frameRoot = null
        runCatching { root?.let { wm.removeView(it) } }
        root = null
        super.onDestroy()
    }

    override fun onBind(intent: Intent?): IBinder? = null

    /** Вьюха ручного выделения области: затемнение + тянущийся прямоугольник. */
    private inner class RegionDrawView(context: Context) : View(context) {
        private val rect = RectF()
        private var hasRect = false
        private val fill = Paint().apply {
            color = 0x334A7EAF
            style = Paint.Style.FILL
        }
        private val stroke = Paint().apply {
            color = 0xFF4A7EAF.toInt()
            style = Paint.Style.STROKE
            strokeWidth = 4f
        }

        fun setRect(x1: Float, y1: Float, x2: Float, y2: Float) {
            // Координаты касания — экранные; окно селектора полноэкранное
            // с (0,0) в левом верхнем углу, совпадает.
            rect.set(minOf(x1, x2), minOf(y1, y2), maxOf(x1, x2), maxOf(y1, y2))
            hasRect = true
            invalidate()
        }

        /** Нормализованные доли экрана 0..1 или null, если слишком маленькая. */
        fun normalized(wPx: Int, hPx: Int): Region? {
            if (!hasRect || rect.width() < 40 || rect.height() < 40) return null
            return Region(
                (rect.left / wPx).coerceIn(0f, 1f),
                (rect.top / hPx).coerceIn(0f, 1f),
                (rect.right / wPx).coerceIn(0f, 1f),
                (rect.bottom / hPx).coerceIn(0f, 1f),
            )
        }

        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            if (!hasRect) return
            canvas.drawRect(rect, fill)
            canvas.drawRect(rect, stroke)
        }
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.accessibilityservice.AccessibilityService
import android.accessibilityservice.GestureDescription
import android.content.Context
import android.graphics.Path
import android.os.Handler
import android.os.Looper
import android.view.accessibility.AccessibilityEvent
import eu.kanade.tachiyomi.util.system.toast
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.withTimeoutOrNull
import kotlin.math.abs

/**
 * Служба доступности — только чтобы отправлять чужому приложению свайпы.
 *
 * Своей прокрутки у чужого приложения взять нельзя: листать его можно
 * лишь жестом, который кто-то должен отправить. Единственный доступный
 * способ — [android.accessibilityservice.AccessibilityService].
 *
 * Ничего больше служба не делает: события не читает, узлы не обходит и
 * ничего не выполняет. Ровно один жест — свайп по заданным координатам.
 */
class OverlayGestureService : AccessibilityService() {

    override fun onServiceConnected() {
        instance = this
    }

    override fun onDestroy() {
        if (instance === this) instance = null
        super.onDestroy()
    }

    /** Служба ни на что не подписана и не должна мешатьTalkBack. */
    override fun onInterrupt() = Unit

    override fun onAccessibilityEvent(event: AccessibilityEvent?) = Unit

    companion object {
        @Volatile
        var instance: OverlayGestureService? = null
            private set

        /**
         * Поток, на котором Android ждёт результат жеста.
         *
         * Отдельный от потока сервиса оверлея: жест отправляет цикл чтения, а
         * колбэк Android обязан получить на лоопере, который живёт, пока
         * работает сама служба доступности.
         */
        private val callbackHandler by lazy { Handler(Looper.getMainLooper()) }

        /** Включена ли служба в настройках Android. */
        fun isEnabled(): Boolean = instance != null

        /**
         * Отправляет один свайп.
         *
         * @param fromX,fromY начало жеста в пикселях экрана
         * @param toX,toY конец жеста
         * @param durationMs длительность жеста: слишком короткий пролистывает
         *   на полстраницы мимо текста, слишком длинный Android не засчитывает
         *   как свайп вовсе
         * @return true, если жест ушёл в систему
         */
        fun swipe(fromX: Int, fromY: Int, toX: Int, toY: Int, durationMs: Long = SWIPE_MS): Boolean {
            val service = instance ?: return false
            if (abs(fromX - toX) < 1 && abs(fromY - toY) < 1) return false
            val path = Path().apply {
                moveTo(fromX.toFloat(), fromY.toFloat())
                lineTo(toX.toFloat(), toY.toFloat())
            }
            val gesture = GestureDescription.Builder()
                .addStroke(
                    GestureDescription.StrokeDescription(path, 0, durationMs.coerceIn(50L, 3_000L)),
                )
                .build()
            return service.dispatchGesture(gesture, null, null) == true
        }

        /**
         * Свайп с ожиданием результата.
         *
         * [swipe] возвращает лишь «жест отправлен в систему» — этого
         * недостаточно: Android может отклонить жест уже по ходу (занято
         * окно, приложение перехватило), и читатель узнаёт об этом только по
         * тому, что следующий кадр совпал с предыдущим. Здесь результат
         * сообщается системой: true — жест отработал, false — отклонён.
         */
        suspend fun swipeAndAwait(
            fromX: Int,
            fromY: Int,
            toX: Int,
            toY: Int,
            durationMs: Long = SWIPE_MS,
        ): Boolean = swipeAndAwait(GestureSwipe(fromX, fromY, toX, toY), durationMs)

        /** То же для готового описания жеста. */
        suspend fun swipeAndAwait(swipe: GestureSwipe, durationMs: Long = SWIPE_MS): Boolean {
            val service = instance ?: return false
            if (abs(swipe.fromX - swipe.toX) < 1 && abs(swipe.fromY - swipe.toY) < 1) return false
            val path = Path().apply {
                moveTo(swipe.fromX.toFloat(), swipe.fromY.toFloat())
                lineTo(swipe.toX.toFloat(), swipe.toY.toFloat())
            }
            val gesture = GestureDescription.Builder()
                .addStroke(
                    GestureDescription.StrokeDescription(path, 0, durationMs.coerceIn(50L, 3_000L)),
                )
                .build()
            val result = CompletableDeferred<Boolean>()
            val sent = service.dispatchGesture(
                gesture,
                object : AccessibilityService.GestureResultCallback() {
                    override fun onCompleted(gestureDescription: GestureDescription?) {
                        result.complete(true)
                    }

                    override fun onCancelled(gestureDescription: GestureDescription?) {
                        result.complete(false)
                    }
                },
                callbackHandler,
            )
            if (!sent) return false
            return withTimeoutOrNull(GESTURE_TIMEOUT_MS) { result.await() } ?: false
        }

        /**
         * Свайп вверх по центру области: так листают вперёд.
         *
         * Жест идёт по вертикали центра рамки, а не всего экрана, иначе
         * палец уезжал бы в область, которую приложение не слушает.
         */
        fun scrollForward(rect: android.graphics.Rect): Boolean {
            if (rect.width() <= 0 || rect.height() <= 0) return false
            val cx = rect.centerX()
            val fromY = rect.centerY() + (rect.height() * 0.30f).toInt()
            val toY = rect.centerY() - (rect.height() * 0.30f).toInt()
            return swipe(cx, fromY, cx, toY)
        }

        /** Свайп вниз — вернуться назад. */
        fun scrollBack(rect: android.graphics.Rect): Boolean {
            if (rect.width() <= 0 || rect.height() <= 0) return false
            val cx = rect.centerX()
            val fromY = rect.centerY() - (rect.height() * 0.30f).toInt()
            val toY = rect.centerY() + (rect.height() * 0.30f).toInt()
            return swipe(cx, fromY, cx, toY)
        }

        private const val SWIPE_MS = 320L

        /** Сколько ждать ответа системы по жесту, мс. */
        private const val GESTURE_TIMEOUT_MS = 3_000L
    }
}

/** Прямоугольный жест: откуда и куда вести пальцем, в пикселях экрана. */
data class GestureSwipe(
    val fromX: Int,
    val fromY: Int,
    val toX: Int,
    val toY: Int,
)

/** Показывает, что служба выключена, и ведёт в настройки доступности. */
fun Context.requestGestureService() {
    runCatching {
        startActivity(
            android.content.Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)
                .addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK),
        )
    }.onFailure { toast("Открой Настройки → Специальные возможности") }
}

