/**
 * Одна круглая кнопка строки меню.
 *
 * Наполнение — либо [icon], либо текстовый [glyph] («♀»/«♂» для выбора пола
 * голоса: символ не подобрать в наборе иконок). Цвета задаёт вызывающий,
 * потому что у разных пунктов смысл подсветки разный (идёт чтение / включён
 * тумблер / просто действие).
 */
data class OcrMenuAction(
    val icon: ImageVector? = null,
    /** Текстовый глиф вместо иконки: «♀»/«♂». */
    val glyph: String? = null,
    val onClick: () -> Unit,
    /** Подсветить кнопку как активную, если [containerColor] не задан явно. */
    val active: Boolean = false,
    val enabled: Boolean = true,
    val containerColor: Color? = null,
    /** Цвет иконки ИЛИ глифа; по умолчанию — контрастный к контейнеру. */
    val contentColor: Color? = null,
    val contentDescription: String? = null,
)

/**
 * Строка меню: подпись слева, одна-три круглые кнопки справа.
 */
data class OcrMenuRow(
    val label: String,
    val action: OcrMenuAction,
    val secondary: OcrMenuAction? = null,
    val tertiary: OcrMenuAction? = null,
    /**
     * Строка-вставка под этой строкой (слайдер скорости и т.п.): модель
     * описывает только круглые кнопки, а такие блоки привязаны к конкретному
     * пункту и должны идти сразу за ним, а не в общий хвост карточки.
     */
    val below: (@Composable ColumnScope.() -> Unit)? = null,
)

/**
 * Карточка плавающего меню. Общая для читалки и (в следующей волне) для
 * оверлея поверх чужих приложений, поэтому всё, что влияет на внешний вид
 * и поведение, задаётся параметрами, а не зашито внутрь.
 *
 * Ширина фиксированная (220..320.dp): раньше карточка была wrap-content, и
 * подписи «рвались» — короткие прижимались к кнопке, длинные уезжали влево.
 * Теперь у всех строк один левый край, а разрыв между подписью и кнопкой
 * даёт отступ.
 */
@Composable
fun OcrControlMenuCard(
    rows: List<OcrMenuRow>,
    modifier: Modifier = Modifier,
    maxHeight: Dp = 480.dp,
    /** Строка статуса над пунктами (в читалке не нужна, в оверлее — да). */
    status: String? = null,
    statusAction: OcrMenuAction? = null,
    /** Подпись версии внизу карточки. */
    footer: String? = null,
    /** Дополнительные строки, которые не влезают в модель (слайдер, конструктор). */
    extraContent: @Composable ColumnScope.() -> Unit = {},
) {
    Card(
        modifier = modifier.widthIn(min = 220.dp, max = 320.dp),
        // Фон строго непрозрачный. Эта же карточка потом поедет оверлеем поверх
        // чужих приложений: при alpha ~0.96 сквозь панель просвечивал чужой
        // текст и подписи рядом с ним становились нечитаемыми.
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surfaceContainerHigh,
        ),
    ) {
        Column(
            modifier = Modifier
                .verticalScroll(rememberScrollState())
                // Пунктов бывает много (конструктор добавляет свои), но панель
                // не должна вылезать за экран — вызывающий подставляет своё
                // значение (в читалке 480.dp, в оверлее — по высоте экрана).
                .heightIn(max = maxHeight)
                .padding(10.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            if (status != null) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        text = status,
                        modifier = Modifier.weight(1f),
                        style = MaterialTheme.typography.labelMedium,
                        maxLines = 2,
                        overflow = TextOverflow.Ellipsis,
                    )
                    if (statusAction != null) {
                        Spacer(Modifier.width(8.dp))
                        OcrMenuActionButton(statusAction)
                    }
                }
            }
            rows.forEach { row ->
                OcrMenuRowContent(row)
                // Вставка под конкретным пунктом (например, слайдером
                // скорости под строкой автопрокрутки).
                val below = row.below
                if (below != null) {
                    below(this)
                }
            }
            extraContent()
            if (footer != null) {
                Spacer(Modifier.height(4.dp))
                Text(
                    text = footer,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.55f),
                )
            }
        }
    }
}

/**
 * Строка меню целиком. Подпись занимает [Modifier.weight], кнопки прижаты
 * к правому краю — отступы между ними одинаковые на каждой строке.
 */
@Composable
private fun OcrMenuRowContent(row: OcrMenuRow) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(
            text = row.label,
            modifier = Modifier.weight(1f),
            style = MaterialTheme.typography.labelMedium,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis,
        )
        Spacer(Modifier.width(8.dp))
        // Подпись строки — запасное описание для кнопки: у глифов («♀»/«♂»)
        // TalkBack нечего прочитать, а у иконок описание может быть пустым.
        OcrMenuActionButton(row.action.withFallbackDescription(row.label))
        row.secondary?.let {
            Spacer(Modifier.width(8.dp))
            OcrMenuActionButton(it.withFallbackDescription(row.label))
        }
        row.tertiary?.let {
            Spacer(Modifier.width(8.dp))
            OcrMenuActionButton(it.withFallbackDescription(row.label))
        }
    }
}

private fun OcrMenuAction.withFallbackDescription(fallback: String) =
    if (contentDescription.isNullOrBlank()) copy(contentDescription = fallback) else this

/**
 * Круглая кнопка строки меню. Вынесена наружу, чтобы [OcrControlMenuCard]
 * и дополнительные блоки (слайдер, кнопки конструктора) рисовали кнопки
 * одинаково.
 */
@Composable
fun OcrMenuActionButton(
    action: OcrMenuAction,
    modifier: Modifier = Modifier,
) {
    // У SmallFloatingActionButton в Material3 нет параметра enabled, поэтому
    // заблокированное состояние рисуем сами: приглушённые цвета плюс защита
    // в обработчике. Иначе кнопка выглядела бы живой, но ничего не делала.
    val enabled = action.enabled
    // Контейнер по умолчанию — тот же surfaceContainerHigh, что у фона карточки:
    // кнопка должна читаться как элемент панели, а не как пятно на её фоне.
    val container = when {
        !enabled -> MaterialTheme.colorScheme.surfaceContainerHigh.copy(alpha = 0.45f)
        action.containerColor != null -> action.containerColor
        action.active -> MaterialTheme.colorScheme.primaryContainer
        else -> MaterialTheme.colorScheme.surfaceContainerHigh
    }
    val content = when {
        !enabled -> MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.35f)
        action.contentColor != null -> action.contentColor
        action.active && action.containerColor == null -> MaterialTheme.colorScheme.onPrimaryContainer
        else -> MaterialTheme.colorScheme.onSurfaceVariant
    }
    val description = action.contentDescription
    SmallFloatingActionButton(
        onClick = { if (enabled) action.onClick() },
        modifier = modifier.then(
            // Описание вешаем на саму кнопку, а не на иконку: у глифа-текста
            // иконки нет вообще, и TalkBack молчал бы.
            if (description.isNullOrBlank()) {
                Modifier
            } else {
                Modifier.semantics { contentDescription = description }
            },
        ),
        containerColor = container,
        contentColor = content,
    ) {
        val glyph = action.glyph
        val icon = action.icon
        when {
            glyph != null -> Text(glyph)
            icon != null -> Icon(icon, contentDescription = null)
        }
    }
}

/**
 * Кнопка-тумблер меню: тап открывает/закрывает панель, перетаскивание двигает
 * её по экрану.
 *
 * Жест разведён отдельной обёрткой [Box] с [detectDragGestures] вокруг FAB —
 * иначе тап и перетаскивание конфликтуют и кнопка «уезжает» вместо
 * открытия меню. Смещения наружу не пишем намеренно: вызывающий держит
 * позицию (и сохраняет её сам), компонент про смещения ничего не знает.
 */
@Composable
fun OcrControlFab(
    expanded: Boolean,
    onToggle: () -> Unit,
    modifier: Modifier = Modifier,
    onDrag: (Offset) -> Unit = {},
    onDragEnd: () -> Unit = {},
    /** Описание для TalkBack; если не задано — по состоянию кнопки. */
    contentDescription: String? = null,
) {
    // pointerInput не перезапускаем на каждый рекомпозиш (иначе жест рвётся
    // посреди перетаскивания), поэтому берём свежие колбэки через state.
    val currentOnDrag by rememberUpdatedState(onDrag)
    val currentOnDragEnd by rememberUpdatedState(onDragEnd)
    Box(
        modifier = modifier.pointerInput(Unit) {
            detectDragGestures(
                onDragEnd = { currentOnDragEnd() },
            ) { change, dragAmount ->
                change.consume()
                currentOnDrag(dragAmount)
            }
        },
    ) {
        FloatingActionButton(
            onClick = onToggle,
            containerColor = MaterialTheme.colorScheme.primary,
        ) {
            Icon(
                if (expanded) Icons.Outlined.Close else Icons.Outlined.Menu,
                contentDescription = contentDescription
                    ?: if (expanded) "Закрыть меню" else "Меню",
            )
        }
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.content.Context
import android.graphics.Bitmap
import android.graphics.Rect
import android.util.Log
import eu.kanade.tachiyomi.data.tts.TtsSpeaker
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import mihon.data.ocr.OcrPlugins
import mihon.domain.ocr.model.OcrImage
import mihon.domain.ocr.repository.OcrRepository
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import kotlin.coroutines.coroutineContext

/**
 * Чтение рамки поверх чужого приложения.
 *
 * Цикл: снять кадр области → распознать → озвучить → дождаться конца
 * речи → отправить свайп → повторить.
 *
 * Скролл наш собственный, а не приложения: приложение может вообще не
 * иметь прокрутки или листать по-своему, поэтому продвижение выполняется
 * жестом через [OverlayGestureService].
 */
class OverlayAutoReader(
    private val context: Context,
    private val capture: OverlayCaptureEngine,
) {
    private val prefs: OcrPreferences by lazy { Injekt.get() }

    /** Сколько ждать конца речи перед прокруткой, мс. */
    private val pauseAfterSpeechMs: Long get() = prefs.overlayReadPause().get().coerceIn(0, 10_000).toLong()

    /** Столько ждём после свайпа, пока приложение перерисует кадр. */
    private val settleAfterScrollMs: Long get() = prefs.overlayScrollSettle().get().coerceIn(200, 5_000).toLong()

    private val scrollDistance: Float
        get() = prefs.overlayScrollStep().get().coerceIn(10, 90) / 100f

    /**
     * Движок оверлея — тот, что выбран для домена «приложения».
     *
     * Вызывается только когда переключатель «свой движок» включён: тогда
     * распознавание идёт именно им, а не движком читалки.
     */
    private fun engineModel(): mihon.domain.ocr.model.OcrModel = prefs.appOcrEngine().get()

    /** Что на самом деле распознаёт: свой движок оверлея или движок читалки. */
    private fun currentModel(): mihon.domain.ocr.model.OcrModel =
        if (prefs.overlayOwnEngine().get()) engineModel() else prefs.ocrModel().get()

    fun engineTitle(): String = OcrPlugins.byModel(currentModel()).title

    /**
     * Один кадр области, распознанный в текст.
     *
     * @return текст или null, если кадр не удалось снять/прочитать
     */
    suspend fun readOnce(region: Rect): String? = withContext(Dispatchers.IO) {
        val bmp = runCatching { capture.capture(region) }.getOrNull() ?: return@withContext null
        try {
            val pixels = IntArray(bmp.width * bmp.height)
            bmp.getPixels(pixels, 0, bmp.width, 0, 0, bmp.width, bmp.height)
            val image = OcrImage(bmp.width, bmp.height, pixels)
            // Движок передаётся явно: иначе распознавание всё равно ушло бы
            // в движок читалки, и переключатель «свой движок» ничего бы не
            // менял, кроме подписи на кнопке.
            Injekt.get<OcrRepository>()
                .recognizeText(image, if (prefs.overlayOwnEngine().get()) engineModel() else null)
                .trim()
                .takeIf { it.isNotBlank() }
        } catch (e: Exception) {
            Log.e(TAG, "overlay read failed", e)
            null
        } finally {
            if (!bmp.isRecycled) bmp.recycle()
        }
    }

    /**
     * Запускает цикл чтения.
     *
     * @param onPage сообщает, что распознан новый экран (для панели оверлея)
     * @param onNote сообщает, что делает цикл (для панели оверлея)
     * @return задача цикла — её отмена останавливает чтение
     */
    fun start(
        scope: CoroutineScope,
        region: Rect,
        onPage: (String) -> Unit = {},
        onNote: (String) -> Unit = {},
    ): Job = scope.launch {
        var lastText: String? = null
        var repeats = 0
        onNote("Чтение начато · ${engineTitle()}")

        // Служба доступности может подключиться позже, чем нажали «Читать»:
        // пока она выключена, листать нечем, и раньше цикл молча завершался
        // после первой реплики. Теперь ждём и продолжаем.
        if (!awaitGestureService(onNote)) return@launch

        while (isActive) {
            val text = readOnce(region)
            if (text == null) {
                onNote("Не удалось прочитать кадр")
                // Кадр может не успеть прогрузиться; ждать и пробовать
                // снова вхолостую только жжёт батарею.
                delay(RETRY_DELAY_MS)
                continue
            }

            // Один и тот же текст после прокрутки означает, что приложение
            // не пролистнулось: озвучивать его второй раз бессмысленно, и
            // цикл ушёл бы в бесконечный повтор одного и того же.
            if (text == lastText) {
                repeats++
                if (repeats >= MAX_REPEATS) {
                    onNote("Приложение не пролистывается — листаю иначе")
                    // Последняя попытка: свайп длиннее и из другой точки.
                    // Некоторые приложения слушают жест только у самого низа
                    // экрана, и свайп по центру рамки они игнорируют.
                    if (!scrollWithFallback(region)) {
                        onNote("Прокрутка не идёт — проверьте Службу доступности")
                        return@launch
                    }
                    repeats = 0
                }
            } else {
                repeats = 0
                lastText = text
                onPage(text)
                speakAndWait(text)
            }

            if (!scrollForward(region)) return@launch
            delay(settleAfterScrollMs)
        }
    }

    /**
     * Ждёт включения Службы доступности, пока её нет.
     *
     * Раньше цикл на первой же неудаче просто завершался, и читатель видел
     * одну озвученную реплику без прокрутки и без объяснения. Теперь при
     * выключенной службе чтение честно ждёт и говорит, что именно надо
     * включить, но ждёт не бесконечно: иначе кнопка «Стоп» пришлось бы искать
     * вслепую.
     *
     * @return false, если службу так и не включили либо чтение отменили
     */
    private suspend fun awaitGestureService(onNote: (String) -> Unit): Boolean {
        var waited = 0L
        // currentCoroutineContext(), а не isActive: здесь нет CoroutineScope,
        // и isActive без получателя просто не разрешается.
        while (currentCoroutineContext().isActive &&
            !OverlayGestureService.isEnabled() &&
            waited < GESTURE_WAIT_MAX_MS
        ) {
            if (waited == 0L) onNote("Включите Службу доступности — жду, чтобы листать")
            delay(GESTURE_WAIT_MS)
            waited += GESTURE_WAIT_MS
        }
        if (!OverlayGestureService.isEnabled()) {
            onNote("Без Службы доступности листать нечем — чтение остановлено")
            return false
        }
        return currentCoroutineContext().isActive
    }

    /**
     * Прокрутка вперёд с проверкой результата.
     *
     * Прежний код останавливал чтение на первом же отказе жеста, и читатель
     * слышал одну реплику — после неё не было ни прокрутки, ни объяснения.
     * Теперь отказ не завершает чтение: жест повторяется, а если и он не
     * прошёл, причина называется прямо.
     */
    private suspend fun scrollForward(region: Rect): Boolean {
        repeat(SCROLL_ATTEMPTS) {
            if (OverlayGestureService.swipeAndAwait(verticalSwipe(region, scrollDistance))) return true
            delay(SCROLL_RETRY_MS)
        }
        // Жест уходит, но экран не меняется: значит точка не слушается.
        return scrollWithFallback(region)
    }

    /** Свайп у самого низа рамки и длиннее обычного — последний довод. */
    private suspend fun scrollWithFallback(region: Rect): Boolean {
        val dy = (region.height() * FALLBACK_STEP).toInt()
        if (dy < 1) return false
        val x = region.left + (region.width() * FALLBACK_X).toInt()
        return OverlayGestureService.swipeAndAwait(
            fromX = x,
            fromY = region.bottom - (region.height() * 0.05f).toInt(),
            toX = x,
            toY = region.bottom - (region.height() * 0.05f).toInt() - dy,
            durationMs = FALLBACK_MS,
        )
    }

    /** Пара координат свайпа по центру области на долю [fraction] её высоты. */
    private fun verticalSwipe(region: Rect, fraction: Float): GestureSwipe {
        val dy = (region.height() * fraction).toInt()
        val cx = region.centerX()
        val cy = region.centerY()
        return GestureSwipe(cx, cy + dy, cx, cy - dy)
    }

    /**
     * Озвучивает и ждёт конца речи, затем паузу.
     *
     * `TtsSpeaker` не отдаёт «прочитано» промисом, но сообщает состояние
     * через колбэк: [onState] приходит false, когда речь закончилась.
     */
    private suspend fun speakAndWait(text: String) {
        val done = kotlinx.coroutines.CompletableDeferred<Unit>()
        var started = false
        TtsSpeaker.speak(context, text) { speaking ->
            if (speaking) {
                started = true
            } else if (started) {
                done.complete(Unit)
            }
        }
        // Если движок не сообщил о начале (например, голос не найден),
        // ждать завершения бессмысленно — цикл обязан идти дальше.
        if (!started) {
            delay(NO_SPEECH_GRACE_MS)
            return
        }
        withTimeoutOrNull(MAX_SPEECH_MS) { done.await() }
        if (coroutineContext.isActive && pauseAfterSpeechMs > 0) delay(pauseAfterSpeechMs)
    }

    /**
     * Листать назад по одному экрану — кнопка «▲ назад» на панели.
     *
     * Работает и без запущенного цикла чтения: пригодится, чтобы вернуться к
     * предыдущей реплике вручную.
     */
    suspend fun scrollBack(region: Rect): Boolean {
        val dy = (region.height() * scrollDistance).toInt()
        if (dy < 1) return false
        val cx = region.centerX()
        val cy = region.centerY()
        return OverlayGestureService.swipeAndAwait(GestureSwipe(cx, cy - dy, cx, cy + dy))
    }

    companion object {
        private const val TAG = "OverlayAutoReader"
        private const val RETRY_DELAY_MS = 900L

        /** Сколько ждать, если движок вообще не начал говорить. */
        private const val NO_SPEECH_GRACE_MS = 300L

        /** Потолок одной реплики: иначе зависший движок стопорит цикл. */
        private const val MAX_SPEECH_MS = 5 * 60_000L

        /** Сколько одинаковых кадров подряд считаем «не пролисталось». */
        private const val MAX_REPEATS = 2

        /** Сколько раз повторить жест, прежде чем менять геометрию. */
        private const val SCROLL_ATTEMPTS = 2

        /** Пауза между попытками жеста, мс. */
        private const val SCROLL_RETRY_MS = 350L

        /** Как часто проверять, не включили ли Службу доступности, мс. */
        private const val GESTURE_WAIT_MS = 1_500L

        /** Сколько ждать включения Службы, прежде чем остановить чтение, мс. */
        private const val GESTURE_WAIT_MAX_MS = 90_000L

        /** Доля высоты области для запасного свайпа. */
        private const val FALLBACK_STEP = 0.7f

        /** Запасной свайп идёт левее центра: там меньше всего кнопок. */
        private const val FALLBACK_X = 0.35f

        /** Запасной свайп длиннее и медленнее — его замечают даже «вялые» списки. */
        private const val FALLBACK_MS = 480L
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.content.Context
import android.graphics.Bitmap
import android.graphics.PixelFormat
import android.graphics.Rect
import android.hardware.display.DisplayManager
import android.hardware.display.VirtualDisplay
import android.media.ImageReader
import android.os.Handler
import android.os.HandlerThread
import android.util.DisplayMetrics
import android.util.Log
import android.view.WindowManager

/**
 * Захват экрана через MediaProjection и вырезание рамки.
 *
 * Перенесено из отдельного приложения overlay-reader в основной Yomikai:
 * режим «рамка поверх окна» должен работать без установки второй программы.
 *
 * VirtualDisplay создаётся один раз и держится до остановки — это
 * единственный надёжный путь на Android 14+, где пересоздание дисплеев
 * одноразовыми проекциями запрещено.
 */
class OverlayCaptureEngine(
    context: Context,
    private val projection: android.media.projection.MediaProjection,
) {
    private val appContext = context.applicationContext

    private var thread: HandlerThread? = null
    private var handler: Handler? = null
    private var reader: ImageReader? = null
    private var display: VirtualDisplay? = null
    private var sizeW: Int = 0
    private var sizeH: Int = 0
    private var density: Int = 0

    /** Размер захватываемого экрана в px (актуальны после первого capture). */
    var screenWidth: Int = 0
        private set
    var screenHeight: Int = 0
        private set

    /** Захватить текущий кадр и вернуть битмап области [rect] (в экранных px). */
    fun capture(rect: Rect): Bitmap? {
        if (display == null && !ensureStarted()) return null

        // Статичный экран может долго не порождать новых кадров (AUTO_MIRROR
        // отрисовывает только «грязные» области) — крутимся до 3 секунд.
        val succeedAt = System.currentTimeMillis() + 3000
        var image: android.media.Image? = null
        while (image == null && System.currentTimeMillis() < succeedAt) {
            image = reader?.acquireLatestImage()
            if (image == null) Thread.sleep(120)
        }
        val img = image ?: return null
        return try {
            val full = copyImage(img) ?: return null
            try {
                val left = rect.left.coerceIn(0, full.width - 1)
                val top = rect.top.coerceIn(0, full.height - 1)
                val right = rect.right.coerceIn(left + 1, full.width)
                val bottom = rect.bottom.coerceIn(top + 1, full.height)
                Bitmap.createBitmap(full, left, top, right - left, bottom - top)
            } finally {
                if (!full.isRecycled) full.recycle()
            }
        } finally {
            img.close()
        }
    }

    private fun ensureStarted(): Boolean {
        if (display != null && reader != null) return true
        // Предыдущая попытка могла упасть уже после создания ImageReader:
        // тогда reader остался не-null, а display — null, и ensureStarted()
        // больше никогда не доходил до createVirtualDisplay (захват умирал
        // навсегда). Перед повтором разбираем half-initialized состояние.
        releaseCaptureResources()

        val metrics = DisplayMetrics()
        @Suppress("DEPRECATION")
        (appContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager)
            .defaultDisplay
            .getRealMetrics(metrics)
        sizeW = metrics.widthPixels
        sizeH = metrics.heightPixels
        density = metrics.densityDpi
        screenWidth = sizeW
        screenHeight = sizeH
        if (sizeW <= 0 || sizeH <= 0) return false

        thread = HandlerThread("overlay_capture").also { it.start() }
        handler = Handler(thread!!.looper)
        reader = ImageReader.newInstance(sizeW, sizeH, PixelFormat.RGBA_8888, 2)
        display = try {
            projection.createVirtualDisplay(
                "yomikai_overlay_capture",
                sizeW,
                sizeH,
                density,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                reader!!.surface,
                null,
                handler,
            )
        } catch (e: Exception) {
            Log.e("YomikaiOverlayCapture", "createVirtualDisplay failed", e)
            null
        }
        if (display == null) {
            // Чистим за собой, чтобы следующий capture() честно попробовал снова.
            releaseCaptureResources()
        }
        return display != null
    }

    /**
     * Гасит только собственные ресурсы захвата. MediaProjection не трогаем:
     * она принадлежит сервису, и её остановка погасила бы всю сессию.
     */
    private fun releaseCaptureResources() {
        runCatching { display?.release() }
        runCatching { reader?.close() }
        display = null
        reader = null
        handler?.looper?.quitSafely()
        thread?.join(500)
        thread = null
        handler = null
    }

    private fun copyImage(image: android.media.Image): Bitmap? {
        val plane = image.planes[0]
        val buffer = plane.buffer
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        val rowPadding = rowStride - pixelStride * image.width
        if (rowPadding < 0) return null

        val aux = Bitmap.createBitmap(
            image.width + rowPadding / pixelStride,
            image.height,
            Bitmap.Config.ARGB_8888,
        )
        aux.copyPixelsFromBuffer(buffer)
        val bmp = Bitmap.createBitmap(aux, 0, 0, image.width, image.height)
        if (!aux.isRecycled) aux.recycle()
        return bmp
    }

    fun stop() {
        releaseCaptureResources()
        runCatching { projection.stop() }
    }
}

package eu.kanade.tachiyomi.ui.overlay

import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.graphics.drawable.Drawable

/**
 * Приложения телефона, на которых оверлей имеет смысл.
 *
 * Читалка оверлея нужна не только для манги: игра на чужом языке, русский
 * текст без озвучки, субтитры к видео в реальном времени — во всех трёх
 * случаях нужен один и тот же список приложений, на которые её можно
 * наложить.
 *
 * Запрашиваются только запускаемые приложения (MAIN + LAUNCHER): этого хватает
 * для списка, и обходится без QUERY_ALL_PACKAGES, который в Google Play не
 * проходит.
 */
object InstalledApps {

    data class Entry(
        val packageName: String,
        val label: String,
        val icon: Drawable?,
    )

    /**
     * Состояние списка. Ошибка показывается читателю, а не молча даёт пустой
     * экран: иначе непонятно, приложений нет или список не прочитался.
     */
    sealed interface AppsState {
        data object Loading : AppsState
        data class Ready(val entries: List<Entry>) : AppsState
        data class Failed(val reason: String) : AppsState
    }

    fun loadState(context: Context): AppsState = runCatching { list(context) }
        .fold(
            onSuccess = { AppsState.Ready(it) },
            onFailure = { AppsState.Failed(it.message ?: it.javaClass.simpleName) },
        )

    fun list(context: Context): List<Entry> {
        val pm = context.packageManager
        val launchIntent = Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER)
        val activities = runCatching {
            pm.queryIntentActivities(launchIntent, 0)
        }.getOrElse { emptyList() }
        return activities.asSequence()
            .mapNotNull { info ->
                val pkg = info.activityInfo?.packageName ?: return@mapNotNull null
                // Свой оверлей поверх самого себя бессмысленен.
                if (pkg == context.packageName) return@mapNotNull null
                val label = runCatching { info.loadLabel(pm).toString() }
                    .getOrNull()
                    ?.takeIf { it.isNotBlank() }
                    ?: pkg
                Entry(
                    packageName = pkg,
                    label = label,
                    icon = runCatching { info.loadIcon(pm) }.getOrNull(),
                )
            }
            // Одинаковые ярлыки бывают у дубликатов (рабочий/профиль) — в списке
            // это шум, поэтому оставляем по одному имени.
            .distinctBy { it.label }
            .sortedBy { it.label.lowercase() }
            .toList()
    }

    /** Запустить выбранное приложение. */
    fun launch(context: Context, packageName: String): Boolean = runCatching {
        val intent = context.packageManager
            .getLaunchIntentForPackage(packageName)
            ?.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            ?: return false
        context.startActivity(intent)
        true
    }.getOrDefault(false)
}

package eu.kanade.tachiyomi.ui.overlay

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.media.projection.MediaProjectionManager
import android.os.Bundle
import android.widget.Toast
import androidx.activity.ComponentActivity
import androidx.activity.result.contract.ActivityResultContracts
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Добывает системное разрешение на захват экрана и передаёт его оверлею.
 *
 * Android не даёт начать MediaProjection из фонового сервиса: диалог
 * разрешения и его результат доступны только activity. Поэтому панель
 * оверлея (это сервис) поднимает прозрачную activity, которая на экране
 * не видна: она только спрашивает и сразу закрывается.
 */
class OcrCaptureActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        requestCapture()
    }

    private fun requestCapture() {
        val mpm = getSystemService(Context.MEDIA_PROJECTION_SERVICE) as? MediaProjectionManager
        if (mpm == null) {
            fail("Захват экрана недоступен")
            return
        }
        if (!hasRegion()) {
            fail("Сначала выделите область рамки кнопкой ✏")
            return
        }
        runCatching { captureLauncher.launch(mpm.createScreenCaptureIntent()) }
            .onFailure { fail("Захват экрана недоступен") }
    }

    /** Задана ли область рамки: без неё захват запускать незачем. */
    private fun hasRegion(): Boolean =
        Injekt.get<OcrPreferences>().overlayFixedRegion().get()
            .split(',')
            .mapNotNull { it.trim().toFloatOrNull() }
            .takeIf { it.size == 4 }
            ?.let { (l, t, r, b) -> l < r && t < b } == true

    private val captureLauncher = registerForActivityResult(
        ActivityResultContracts.StartActivityForResult(),
    ) { result ->
        val data = result.data
        if (result.resultCode != RESULT_OK || data == null) {
            fail("Захват экрана не разрешён")
            return@registerForActivityResult
        }
        OcrOverlayService.startReading(this, result.resultCode, data)
        finish()
    }

    private fun fail(message: String) {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
        finish()
    }

    companion object {
        /** Поднимает прозрачную activity, которая спросит разрешение. */
        fun request(context: Context) {
            runCatching {
                context.startActivity(
                    Intent(context, OcrCaptureActivity::class.java)
                        .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK),
                )
            }.onFailure {
                Toast.makeText(context, "Захват экрана недоступен", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

